-- Generated by `make contracts` from contracts/cdc_respnet.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'cdc_respnet') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "surveillance_network" AS "surveillance_network",
  "season" AS "season",
  "date_type" AS "date_type",
  "date" AS "date",
  "age_category" AS "age_category",
  "race" AS "race",
  "sex" AS "sex",
  "state" AS "state",
  "data_type" AS "data_type",
  "estimate_type" AS "estimate_type",
  "rate_type" AS "rate_type",
  CAST(NULLIF(trim("estimate"), '') AS DOUBLE) AS "estimate"
from latest
